// Alle Dateien und Ordner aus Drive aufbereiten
const items = $input.all();

const files = [];
const folders = [];
const md5Map = {};
const duplicates = [];

for (const item of items) {
  const f = item.json;

  // Überspringe gelöschte Elemente
  if (f.trashed) continue;

  const entry = {
    id: f.id,
    name: f.name,
    mimeType: f.mimeType || 'unknown',
    size: f.size || 0,
    modifiedTime: f.modifiedTime,
    parents: f.parents || [],
    md5: f.md5Checksum || null,
    isFolder: f.mimeType === 'application/vnd.google-apps.folder',
    isGoogleDoc: f.mimeType?.startsWith('application/vnd.google-apps.') && f.mimeType !== 'application/vnd.google-apps.folder',
    extension: f.name?.split('.').pop()?.toLowerCase() || '',
    category: null
  };

  if (entry.isFolder) {
    folders.push(entry);
  } else {
    // Duplikate per MD5 erkennen
    if (entry.md5) {
      if (md5Map[entry.md5]) {
        md5Map[entry.md5].push(entry.id);
        duplicates.push({ ids: md5Map[entry.md5], name: entry.name, md5: entry.md5 });
      } else {
        md5Map[entry.md5] = [entry.id];
      }
    }
    files.push(entry);
  }
}

console.log(`Gefunden: ${files.length} Dateien, ${folders.length} Ordner, ${duplicates.length} mögliche Duplikat-Gruppen`);

return [
  {
    json: {
      files,
      folders,
      duplicates,
      summary: {
        totalFiles: files.length,
        totalFolders: folders.length,
        duplicateGroups: duplicates.length
      }
    }
  }
];

// Dateiliste in Batches für AI aufteilen (max 80 Dateien pro AI-Anfrage)
const data = $input.first().json;
const files = data.files;
const BATCH_SIZE = 80;
const batches = [];

for (let i = 0; i < files.length; i += BATCH_SIZE) {
  batches.push({
    json: {
      batchIndex: Math.floor(i / BATCH_SIZE),
      totalBatches: Math.ceil(files.length / BATCH_SIZE),
      files: files.slice(i, i + BATCH_SIZE),
      allFolders: data.folders,
      duplicates: data.duplicates,
      summary: data.summary
    }
  });
}

if (batches.length === 0) {
  batches.push({ json: { batchIndex: 0, totalBatches: 1, files: [], allFolders: data.folders, duplicates: data.duplicates, summary: data.summary } });
}

return batches;

