// AI-Antwort parsen und Kategorien extrahieren
const items = $input.all();
const allCategories = [];

for (const item of items) {
  try {
    const content = item.json.message?.content || item.json.choices?.[0]?.message?.content || '';

    // JSON aus der Antwort extrahieren
    let parsed;
    const jsonMatch = content.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      parsed = JSON.parse(jsonMatch[0]);
    } else {
      parsed = JSON.parse(content);
    }

    if (parsed.categories && Array.isArray(parsed.categories)) {
      allCategories.push(...parsed.categories);
    }
  } catch (e) {
    console.error('Fehler beim Parsen der AI-Antwort:', e.message);
  }
}

console.log(`Kategorisiert: ${allCategories.length} Dateien`);

// Einzigartige Pfade/Ordner sammeln
const foldersNeeded = new Set();
for (const cat of allCategories) {
  if (cat.suggestedPath && cat.action !== 'delete_duplicate') {
    const parts = cat.suggestedPath.split('/');
    let currentPath = '';
    for (const part of parts) {
      if (part.trim()) {
        currentPath = currentPath ? `${currentPath}/${part.trim()}` : part.trim();
        foldersNeeded.add(currentPath);
      }
    }
  }
}

return [
  {
    json: {
      categories: allCategories,
      foldersToCreate: Array.from(foldersNeeded).sort(),
      filesToDelete: allCategories.filter(c => c.action === 'delete_duplicate'),
      filesToMove: allCategories.filter(c => c.action === 'move')
    }
  }
];

