// Finale Ordnerstruktur parsen
const aiResponse = $input.first();
const content = aiResponse.json.message?.content || aiResponse.json.choices?.[0]?.message?.content || '';

let structure;
try {
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  structure = jsonMatch ? JSON.parse(jsonMatch[0]) : JSON.parse(content);
} catch(e) {
  console.error('Parse error:', e);
  structure = { optimizedStructure: [], renamedFolders: [], summary: 'Parse error' };
}

console.log('Ordnerstruktur-Zusammenfassung:', structure.summary);
console.log(`Erstelle ${structure.optimizedStructure?.length || 0} Ordner`);

// Ordner nach Tiefe sortieren (erst Parent, dann Children)
const sortedFolders = (structure.optimizedStructure || []).sort((a, b) => {
  const depthA = (a.path || '').split('/').length;
  const depthB = (b.path || '').split('/').length;
  return depthA - depthB;
});

// Ergebnis als einzelne Items zurückgeben
return sortedFolders.map(folder => ({
  json: {
    path: folder.path,
    name: folder.path.split('/').pop(),
    parentPath: folder.parentPath || null,
    description: folder.description,
    depth: folder.path.split('/').length,
    createdFolderId: null
  }
}));

// Folder-ID nach Erstellung speichern
const folderData = $input.first().json;

// Globale Map für erstellte Ordner (via $workflow.staticData)
const staticData = $workflow.staticData;
if (!staticData.createdFolders) staticData.createdFolders = {};

const path = folderData.path || folderData.name;
const folderId = folderData.id;

if (path && folderId) {
  staticData.createdFolders[path] = folderId;
  console.log(`Ordner gespeichert: ${path} -> ${folderId}`);
}

return [{ json: { path, folderId, allFolders: staticData.createdFolders } }];

// Alle Kategorisierungen holen und Dateien zum Verschieben vorbereiten
// Hinweis: $('Code: AI-Antworten zusammenführen') referenziert den früheren Node
const categoriesData = $('Code: AI-Antworten zusammenführen').first().json;
const createdFolders = $workflow.staticData.createdFolders || {};

const filesToMove = categoriesData.filesToMove || [];
const results = [];

for (const file of filesToMove) {
  if (!file.fileId || !file.suggestedPath) continue;

  // Ordner-ID für den Zielpfad finden
  const targetFolderId = createdFolders[file.suggestedPath];

  if (targetFolderId) {
    results.push({
      json: {
        fileId: file.fileId,
        fileName: file.fileName,
        targetFolderId,
        targetPath: file.suggestedPath,
        category: file.category
      }
    });
  } else {
    console.warn(`Kein Ordner gefunden für Pfad: ${file.suggestedPath} (Datei: ${file.fileName})`);
  }
}

console.log(`Verschiebe ${results.length} von ${filesToMove.length} Dateien`);
return results.length > 0 ? results : [{ json: { message: 'Keine Dateien zum Verschieben', count: 0 } }];

// Duplikate vorbereiten
const categoriesData = $('Code: AI-Antworten zusammenführen').first().json;
const filesToDelete = categoriesData.filesToDelete || [];

console.log(`${filesToDelete.length} Duplikate gefunden`);

if (filesToDelete.length === 0) {
  return [{ json: { message: 'Keine Duplikate gefunden', count: 0 } }];
}

return filesToDelete.map(f => ({
  json: {
    fileId: f.fileId,
    fileName: f.fileName,
    duplicateOf: f.duplicateOf,
    action: 'delete'
  }
}));

// Zusammenfassung erstellen
const categoriesData = $('Code: AI-Antworten zusammenführen').first().json;

const summary = {
  timestamp: new Date().toISOString(),
  totalFiles: categoriesData.categories?.length || 0,
  filesMovedSuccessfully: categoriesData.filesToMove?.length || 0,
  duplicatesRemoved: categoriesData.filesToDelete?.length || 0,
  foldersCreated: Object.keys($workflow.staticData.createdFolders || {}).length,
  status: 'Erfolgreich abgeschlossen'
};

console.log('=== ZUSAMMENFASSUNG ===' );
console.log(JSON.stringify(summary, null, 2));

return [{ json: summary }];
